('TA_0003', 'Skip Single-Use Plastic', 'Refuse plastic straws, utensils, or packaging', 'Verify photo showing refusal or alternative used', 1, 3, 5, 12, 'plastic', 0.1500000000, 'daily', 20),
('TA_0004', 'Bike or Walk Short Trips', 'Use bike or walk instead of car for trips under 2km', 'Check photo of bike/walk route or fitness app screenshot', 1, 1, 2, 15, 'carbon', 0.0500000000, 'weekly', (UNIX_TIMESTAMP() / (86400 * 7))),
('TA_0005', 'Unplug Electronics', 'Unplug unused electronics and chargers', 'Photo of unplugged devices or power strip turned off', 1, 5, 5, 5, 'electric', 5.0000000000, 'daily', 40),
('TA_0006', 'Pack Waste-Free Lunch', 'Bring lunch in reusable containers with no disposables', 'Photo of waste-free lunch setup', 1, 1, 0, 20, 'plastic', 0.5000000000, 'daily', 10),
('TA_0007', 'Community Litter Pickup', 'Pick up litter during a walk (5-10 pieces)', 'Before/after photos showing collected litter', 1, 5, 10, 18, 'trash', 10.0000000000, 'weekly', (UNIX_TIMESTAMP() / (86400 * 7)) + 1);
